/// <summary>
/// MPJ_6030_VendorInvoiceDocument
/// </summary>
[ExtensionOf(classStr(VendInvoiceDocumentDP))]
public final class METVendInvoiceDocumentDP_Extension
{
    public Notes       metHeaderNotes;

}

Method.Source:
    /// <summary>
    ///     Populates values into the <c>VendInvoiceDocumentTmp</c> table.
    /// </summary>
    /// <param name="_purchInvoiceTransOrTaxTrans">
    ///     A value that indicates whether it is transaction details or tax details.
    /// </param>
    ///     <param name="_vendPaymSched">
    ///     The <c>vendPaymSched</c> variable.
    /// </param>
    protected void populateVendInvoiceDocumentTmp(NoYes _purchInvoiceTransOrTaxTrans, NoYes _vendPaymSched)
    {
        METALMSupplierVolumetricRebateHeader    metALMSupplierVolumetricRebateHeader;
        VendTable                               metInvoiceAccount = vendInvoiceJour.vendTable_InvoiceAccount();

        next populateVendInvoiceDocumentTmp(_purchInvoiceTransOrTaxTrans, _vendPaymSched);

        vendInvoiceDocumentTmp.METKnownAs = DirPartyTable::findRec(metInvoiceAccount.Party).KnownAs;
        vendInvoiceDocumentTmp.METVendAccount = metInvoiceAccount.AccountNum;
        vendInvoiceDocumentTmp.VendName = metInvoiceAccount.name();

        this.metSetDocumentNote();

        // MPJ_21593 SVR document DCP 06/05/2022
        metALMSupplierVolumetricRebateHeader = METALMSupplierVolumetricRebateHeader::find(vendInvoiceJour.METALMSupplierVolumetricRebateNumber);

        vendInvoiceDocumentTmp.METALMSupplierVolumetricRebateNumber = vendInvoiceJour.METALMSupplierVolumetricRebateNumber;
        vendInvoiceDocumentTmp.METALMCustVendAccount                = metALMSupplierVolumetricRebateHeader.CustomerAccount;
        vendInvoiceDocumentTmp.METALMCustVendName                   = metALMSupplierVolumetricRebateHeader.customerName();
    }

    /// <summary>
    /// Creates data for the report.
    /// MPJ_21593 SVR document DCP 09/05/2022
    /// </summary>
    /// <param name="_contract">
    /// An instance of <c>VendInvoiceDocumentContract</c> report contract class.
    /// </param>
    public void createData(VendInvoiceDocumentContract _contract)
    {
        next createData(_contract);

        this.METAddLine();
    }

    /// <summary>
    /// Create an additional report line METALMSupplierVolumetricRebate
    /// MPJ_21593 SVR document DCP 09/05/2022
    /// </summary>
    public void METAddLine()
    {
        // If there are no Transaction records and the METALMSupplierVolumetricRebateHeader.type = SVR, 
        // then create a extra line for the report.

        Counter                 MetRecordCount;
        VendInvoiceDocumentTmp  MetVendInvoiceDocumentTmpLoc = this.getVendInvoiceDocumentTmp();
        PurchIdBase             MetPurchNum;
        VendInvoiceId           MetInvoiceNum;
        PurchPrice              MetSalesBalance;
        METALMSupplierVolumetricRebateNumber MetRebateNumber;

        select count(recid) from MetVendInvoiceDocumentTmpLoc
            where   MetVendInvoiceDocumentTmpLoc.PurchInvoiceTransOrTaxTrans == NoYes::Yes;

        MetRecordCount = MetVendInvoiceDocumentTmpLoc.recid;

        if(MetRecordCount == 0) ///there are no transaction lines
        {
            select MetVendInvoiceDocumentTmpLoc;

            if(MetVendInvoiceDocumentTmpLoc.METALMSupplierVolumetricRebateNumber
            && METALMSupplierVolumetricRebateHeader::find(MetVendInvoiceDocumentTmpLoc.METALMSupplierVolumetricRebateNumber).Type == METALMSupplierVolumetricRebateType::SVR)
            {
                //get values here as once we call VendInvoiceDocumentTmp.clear()  VendInvoiceDocumentTmpLoc is cleared also.
                MetPurchNum     = MetVendInvoiceDocumentTmpLoc.PurchNum;
                MetInvoiceNum   = MetVendInvoiceDocumentTmpLoc.InvoiceNum;
                MetSalesBalance = MetVendInvoiceDocumentTmpLoc.SalesBalance;
                MetRebateNumber = MetVendInvoiceDocumentTmpLoc.METALMSupplierVolumetricRebateNumber;

                VendInvoiceDocumentTmp.clear();
                VendInvoiceDocumentTmp.PurchNum     = MetPurchNum;
                VendInvoiceDocumentTmp.InvoiceNum   = MetInvoiceNum;
                VendInvoiceDocumentTmp.METALMLine   = NoYes::Yes;
                VendInvoiceDocumentTmp.Name         = LedgerJournalTrans::METfindByMETALMRebateNumber(MetRebateNumber).Txt;
                VendInvoiceDocumentTmp.qty          = 1;
                VendInvoiceDocumentTmp.PurchPrice   = MetSalesBalance;
                VendInvoiceDocumentTmp.LineAmount   = VendInvoiceDocumentTmp.qty * VendInvoiceDocumentTmp.PurchPrice;

                this.insertVendInvoiceDocumentTmp(NoYes::No, NoYes::No);
            }
        }


    }

    /// <summary>
    /// Set document note
    /// </summary>
    public void metSetDocumentNote()
    {

        LedgerJournalTrans  metLedgerJournalTrans;

        if (!metHeaderNotes)
        {
            vendInvoiceDocumentTmp.METHeaderNotes =  this.metGetDocuRef(VendInvoiceInfoTable::findFromVendInvoiceJour(vendInvoiceJour.PurchId,
                                                                                                                      vendInvoiceJour.InvoiceId,
                                                                                                                      vendInvoiceJour.ParmId));
            if (!vendInvoiceDocumentTmp.METHeaderNotes)
            {
                metLedgerJournalTrans = LedgerJournalTrans::findJournalForVoucher(vendInvoiceJour.LedgerVoucher, vendInvoiceJour.InvoiceDate);
                VendInvoiceDocumentTmp.METHeaderNotes =  this.metGetDocuRef(metLedgerJournalTrans.ledgerJournaltable());
            }

            metHeaderNotes = VendInvoiceDocumentTmp.METHeaderNotes;
        }
        else
        {
            VendInvoiceDocumentTmp.METHeaderNotes = metHeaderNotes;
        }


    }

    /// <summary>
    /// Find notes related to reference table record.
    /// </summary>
    /// <param name = "_common">record buffer.</param>
    /// <returns>Notes</returns>
    public Notes metGetDocuRef(Common _common)
    {
        DocuRef     metDocuRef;
        select firstonly Notes from metDocuRef
            where metDocuRef.RefCompanyId  == _common.DataAreaId
                    && metDocuRef.RefTableId    == _common.TableId
                    && metDocuRef.RefRecId      == _common.RecId
                    && metDocuRef.TypeId        == METConstants::Note
                    && metDocuRef.Restriction   == DocuRestriction::External;

        return metDocuRef.Notes;
    }
